import type { ReactNode } from "react";

/** A box that keeps a fixed width to height ratio for what it holds, such as an image, a video or a map. It reserves the space before the content loads, so the page does not jump. */
export interface AspectRatioSpecProps {
  /**
   * Width divided by height as a number (1.5), a "16/9" string, or a preset: square 1/1, video 16/9, photo 3/2, wide 21/9, portrait 3/4.
   * @default "video"
   */
  ratio?: number | "square" | "video" | "photo" | "wide" | "portrait" | `${number}/${number}`;
  /**
   * Rounds the corners with the control radius.
   * @default false
   */
  rounded?: boolean;
  /**
   * The content. Images, video and iframes are stretched to fill the box and cropped to cover it.
   */
  children?: ReactNode;
}

export const aspectRatioDefaults = {
  ratio: "video",
  rounded: false,
} as const;

export const aspectRatioMeta = {
  "name": "AspectRatio",
  "version": "0.1.0",
  "status": "experimental",
  "role": "none"
} as const;
